// Package + upload the hex-cluster printables to R2.
//
//   pnpm tsx scripts/upload-printables.ts            # DRY RUN (default)
//   pnpm tsx scripts/upload-printables.ts --write    # actually uploads
//
// PRINTABLES_EMIT=<dir> makes a dry run WRITE the bytes it would upload, so the
// zip and its README can be opened before anything is published. Worth doing:
// the keys are immutable, so a wrong README costs a new release segment.
//
// Reads the mesh set generated by the PRIVATE hardware repo
// (`otd-dev-hardware/enclosure/tools/build_printables.py`) and pushes it to R2
// under an immutable `printables/{release}/...` prefix. The .FCStd sources stay
// private; only generated meshes ship.
//
// !! THERE IS NO LOCAL R2. !!
// Unlike the database — where `.env.local` points at local Postgres since
// 2026-07-15, so scripts are safe by default — R2_* credentials in `.env.local`
// are the REAL bucket. `--write` therefore uploads to production storage. Hence
// dry run is the default and prints every object it would put, matching the
// convention in scripts/import-content.ts.
//
// Set membership below is a PROPOSAL pending the owner's call on what is free
// vs gated. Edit SETS, not the upload logic.
import { config as loadEnv } from "dotenv";
loadEnv({ path: ".env.local" });

import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import JSZip from "jszip";
import { HeadObjectCommand, PutObjectCommand } from "@aws-sdk/client-s3";

// The print spec, shared with the academy's /hex page. A plain data module with
// no env dependency, so a static import is safe above the dotenv call below.
import {
  HEX_CLEARANCE,
  HEX_ORIENTATION,
  HEX_PRINT_PARAMS,
} from "../src/lib/hex-spec";
// Plain data, no env, so a static import is safe above the dotenv call below --
// same reasoning as hex-spec. See that module on why the list lives in one place.
import {
  NEEDS_SUPPORT_NAMES,
  SUPPORT_NOTE,
  SUPPORT_SLICER_NOTE,
} from "../src/lib/hex-support";

/** Hard-wrap for the archive README, which is read in Notepad and in terminals.
 *  Neither reflows, so a long sentence is either cut off at the column or
 *  scrolls sideways out of view. The academy's README module has its own copy of
 *  this for the same reason; sharing it would mean importing a module that pulls
 *  in the print spec to wrap a string. */
function wrap72(text: string, indent = ""): string[] {
  const out: string[] = [];
  let line = "";
  for (const word of text.split(/\s+/).filter(Boolean)) {
    if (line !== "" && `${indent}${line} ${word}`.length > 72) {
      out.push(indent + line);
      line = word;
    } else {
      line = line === "" ? word : `${line} ${word}`;
    }
  }
  if (line !== "") out.push(indent + line);
  return out;
}

// Dynamic imports inside main() so dotenv populates process.env BEFORE
// src/env.ts validates it at module-eval time (a static import would hoist
// above loadEnv and fail on every var). Same shape as the other scripts here.
type R2Mod = typeof import("../src/lib/r2");
type EnvMod = typeof import("../src/env");

// The mesh set is generated in the PRIVATE hex-cluster repo (a sibling
// checkout), so this is a path out of the tree rather than a repo asset.
const SOURCE_DIR = resolve(
  process.env.PRINTABLES_DIR ?? "../hex-cluster/build/printables",
);

// Immutable release segment. Override to re-cut without clobbering a published
// URL; bump it whenever the meshes change.
const RELEASE = process.env.PRINTABLES_RELEASE ?? "2026-07-31";

// EVERYTHING SHIPS FREE, as one set. There is deliberately no gated tier.
//
// The parts are not the moat -- the curriculum, the validated board designs and
// the configurator are. Gating enclosure furniture to protect curriculum revenue
// protects the wrong asset, and a gated subset cannot rank: Printables and
// MakerWorld surface models on downloads, makes and remixes, so a teaser set
// gets no engagement and dies. Enforcement would be thin regardless (a printed
// functional object carries thin copyright under the useful-article doctrine),
// so a gate mostly taxes honest users.
//
// Lead capture belongs on the CONFIGURATOR ("save your build" / "email me this
// build sheet"), not on the download. Someone who configured a cluster is a warm
// lead; someone who clicked download is not.
//
// Excluded from the public set on DISCLOSURE grounds -- not commercial ones. A
// carrier is shaped around its board, so publishing it publishes that board's
// footprint and connector geometry. TB-1-POWER is a BioScale-BCI program test
// board, and the academy disclosure policy keeps program specifics off public
// surfaces. Add a part here only for that reason; do not use it as a paywall.
const WITHHELD_PARTS = new Set(["TB-1-POWER"]);

const SETS: Record<
  string,
  { label: string; parts: (m: Manifest) => string[] }
> = {
  "hex-cluster": {
    label: "Hex Cluster modular tile system -- complete set",
    parts: (m) =>
      m.parts.map((p) => p.part).filter((p) => !WITHHELD_PARTS.has(p)),
  },
};

type ManifestPart = {
  part: string;
  family: string;
  triangles: number;
  volumeMm3: number;
  bboxMm: { x: number; y: number; z: number };
  borderEdges: number;
  files: Record<string, { path: string; bytes: number; sha256: string }>;
  /** Rotations the exporter baked in to make the part print-ready. EMPTY for a
   *  part left in its CAD pose. Read by the README so it can state which of the
   *  two a downloader is holding, rather than guessing on their behalf. */
  printOrientation?: { axis: string; degrees: number }[];
  /** Whether a human has checked that rotation. False everywhere as of release
   *  2026-07-31, which is exactly why the README says to verify before slicing. */
  printOrientationReviewed?: boolean;
};
type Manifest = { parts: ManifestPart[]; failures: unknown[] };

const write = process.argv.includes("--write");
// Where a DRY RUN drops the bytes it would have uploaded, so the archive can be
// read before it is published. Release keys are immutable and carry a one-year
// `immutable` cache header, so a wrong README is not editable afterwards -- it
// costs a whole new release segment. A dry run that only prints key names cannot
// catch that; one you can open can.
const emitDir = process.env.PRINTABLES_EMIT;
// Re-PUT objects that are already present at the right size. Only needed to
// repair a corrupted upload; the default skip is what makes a run resumable.
const force = process.argv.includes("--force");

// The publish is ~170 objects and 60 MB over one TLS session, and the first two
// real runs both died partway with `ssl3_read_bytes: tls alert bad record mac`
// at different objects. Without a retry AND a skip, every attempt restarts from
// zero and the publish becomes a coin flip that gets more expensive each throw.
//
// Skipping is safe precisely because the keys are IMMUTABLE: a release segment
// is never overwritten, so a key that exists at the expected size holds the
// bytes this run would have written. That is what turns "run it again" into
// "resume", and it is why the check is on size rather than a re-hash.
const MAX_ATTEMPTS = 5;
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

function loadManifest(): Manifest {
  const path = join(SOURCE_DIR, "manifest.json");
  try {
    return JSON.parse(readFileSync(path, "utf8")) as Manifest;
  } catch {
    throw new Error(
      `No manifest at ${path}. Generate it first:\n` +
        `  cd <hardware repo>/enclosure && python tools/build_printables.py`,
    );
  }
}

let r2!: R2Mod["r2"];
let env!: EnvMod["env"];

/** Byte size of an existing object, or null if it is absent (or unreadable). */
async function existingSize(key: string): Promise<number | null> {
  try {
    const out = await r2.send(
      new HeadObjectCommand({ Bucket: env.R2_BUCKET!, Key: key }),
    );
    return out.ContentLength ?? null;
  } catch {
    return null;
  }
}

let skipped = 0;
let retried = 0;

async function put(key: string, body: Buffer, contentType: string) {
  const kb = `${(body.length / 1024).toFixed(0)} KB`;
  if (!write) {
    if (emitDir) {
      const dest = join(emitDir, key);
      mkdirSync(dirname(dest), { recursive: true });
      writeFileSync(dest, body);
    }
    console.log(`  [dry] ${key}  (${kb})`);
    return;
  }

  if (!force && (await existingSize(key)) === body.length) {
    skipped++;
    console.log(`  [skip] ${key}  (already published, ${kb})`);
    return;
  }

  for (let attempt = 1; ; attempt++) {
    try {
      await r2.send(
        new PutObjectCommand({
          Bucket: env.R2_BUCKET!,
          Key: key,
          Body: body,
          ContentType: contentType,
          // Immutable keys (see printableKey) make a long cache safe.
          CacheControl: "public, max-age=31536000, immutable",
        }),
      );
      console.log(`  [put] ${key}  (${kb})`);
      return;
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      if (attempt >= MAX_ATTEMPTS) {
        throw new Error(
          `${key} failed after ${MAX_ATTEMPTS} attempts: ${msg}\n` +
            `Re-run the same command; published objects are skipped, so it resumes.`,
        );
      }
      retried++;
      const wait = 400 * 2 ** (attempt - 1);
      console.log(`  [retry ${attempt}/${MAX_ATTEMPTS - 1}] ${key}: ${msg}`);
      await sleep(wait);
    }
  }
}

const CONTENT_TYPE: Record<string, string> = {
  "3mf": "model/3mf",
  stl: "model/stl",
  step: "application/step",
};

async function main() {
  const r2mod = await import("../src/lib/r2");
  ({ env } = await import("../src/env"));
  r2 = r2mod.r2;
  const { printableKey, printableLicenseKey, printableSetKey } = r2mod;

  if (!env.R2_ENABLED || !env.R2_BUCKET) {
    throw new Error(
      "R2 is not configured (R2_ENABLED / R2_BUCKET). Refusing to run.",
    );
  }

  const manifest = loadManifest();
  console.log(`source:  ${SOURCE_DIR}`);
  console.log(`release: ${RELEASE}`);
  console.log(`bucket:  ${env.R2_BUCKET}`);
  console.log(
    `mode:    ${write ? "WRITE (uploads to the real bucket)" : "DRY RUN"}`,
  );
  console.log(`parts:   ${manifest.parts.length}`);

  // A part that failed the watertight gate is absent from the manifest, so it
  // can never reach the bucket by accident. Say so out loud anyway -- a silently
  // short set is exactly the kind of thing that ships unnoticed.
  if (manifest.failures.length) {
    console.log(
      `\n!! ${manifest.failures.length} source(s) FAILED the export gate and are NOT included.` +
        `\n   Fix those before publishing, or the set is incomplete.`,
    );
  }

  const withheld = manifest.parts.filter((p) => WITHHELD_PARTS.has(p.part));
  if (withheld.length) {
    console.log(
      `\nwithheld (disclosure, not paywall): ${withheld.map((p) => p.part).join(", ")}`,
    );
  }

  // Standalone too, not just inside the zip: anyone grabbing a single .3mf by
  // URL never opens the archive, and CC BY only works if the terms travel.
  await put(
    printableLicenseKey(RELEASE),
    Buffer.from(LICENSE_TXT, "utf8"),
    "text/plain; charset=utf-8",
  );

  console.log("\n-- individual files --");
  for (const part of manifest.parts) {
    if (WITHHELD_PARTS.has(part.part)) continue;
    for (const [format, file] of Object.entries(part.files)) {
      const fmt = format as "3mf" | "stl" | "step";
      const body = readFileSync(join(SOURCE_DIR, file.path));
      await put(
        printableKey(RELEASE, fmt, part.part, fmt),
        body,
        CONTENT_TYPE[fmt],
      );
    }
  }

  console.log("\n-- set archives --");
  for (const [setName, set] of Object.entries(SETS)) {
    const names = set.parts(manifest);
    const zip = new JSZip();
    // The README describes the parts it actually ships with, so it is handed
    // the manifest rows for exactly those names, not the whole manifest.
    const setParts = manifest.parts.filter((p) => names.includes(p.part));
    zip.file("README.txt", setReadme(set.label, names, setParts));
    zip.file("LICENSE.txt", LICENSE_TXT);
    for (const name of names) {
      const part = manifest.parts.find((p) => p.part === name);
      if (!part) continue;
      // 3MF + STL only. STEP is the archival/remix format and stays a
      // per-file download; bundling it would double the zip for no print value.
      for (const fmt of ["3mf", "stl"] as const) {
        const file = part.files[fmt];
        if (!file) continue;
        zip.file(
          `${fmt}/${name}.${fmt}`,
          readFileSync(join(SOURCE_DIR, file.path)),
        );
      }
    }
    const body = await zip.generateAsync({
      type: "nodebuffer",
      compression: "DEFLATE",
    });
    console.log(`  ${setName}: ${names.length} part(s)`);
    await put(printableSetKey(RELEASE, setName), body, "application/zip");
  }

  const base = env.NEXT_PUBLIC_R2_PUBLIC_BASE_URL;
  console.log(
    `\n${write ? "Uploaded" : "Would upload"} release ${RELEASE}.` +
      (write
        ? `\nskipped (already published): ${skipped} · retries: ${retried}`
        : "") +
      (base
        ? `\nPublic base: ${base}/printables/${RELEASE}/`
        : write
          ? `\nNo R2 custom domain set, so the files serve through /api/printable/${RELEASE}/...`
          : ""),
  );
  if (!write) console.log("Re-run with --write to apply.");
}

// The README is deliberately plain ASCII (it uses `--` for dashes throughout),
// because it is read in whatever the downloader's zip viewer or Notepad does
// with encodings. The shared spec is written for the WEB page, so degree signs,
// en dashes and multiplication signs come through it; fold them here rather
// than ASCII-ifying the page.
function ascii(s: string): string {
  return s
    .replace(/°/g, " deg ")
    .replace(/[–—]/g, "-")
    .replace(/×/g, "x")
    .replace(/\s+/g, " ")
    .trim();
}

/** How the shipped meshes are posed, stated from the manifest rather than
 *  asserted. Splits the set into "already rotated for printing" and "still in
 *  its CAD pose", and says plainly whether a human has checked either. */
function orientationNote(parts: ManifestPart[]): string[] {
  const rotated = parts.filter((p) => (p.printOrientation?.length ?? 0) > 0);
  const reviewed = parts.filter((p) => p.printOrientationReviewed);
  const total = parts.length;

  if (rotated.length === 0) {
    return [
      "Every part is exported in its CAD orientation. Check each one sits on a",
      "flat face before slicing.",
    ];
  }

  const lines = [
    `Orientation: ${rotated.length} of the ${total} parts are exported already`,
    `rotated for printing; the remaining ${total - rotated.length} are in their CAD`,
    "orientation.",
  ];
  if (reviewed.length < rotated.length) {
    lines.push(
      "",
      "Those rotations are derived automatically and have NOT been reviewed by",
      "hand. Check every part sits on a flat face before slicing.",
    );
  } else {
    lines.push(
      "",
      "Every orientation has been checked: each part rests on a flat face, with",
      "the two exceptions below. Nobody has printed the set yet, so this is a",
      "geometric check and not a print-tested one.",
    );
  }

  // The parts that rest on a line by DESIGN, named so nobody is surprised
  // mid-print. The list used to be a local const here AND a second one in
  // src/lib/hex-pack-readme.ts, each asking the other to be kept in sync. It now
  // lives once in @/lib/hex-support, because the download endpoint reads the same
  // set to decide whether a single-plate build ships bare or inside an archive --
  // so a re-cut that updated this file and not that one would ship a bare file
  // with no warning in it at all. See that module's header.
  const present = NEEDS_SUPPORT_NAMES.filter((n) =>
    parts.some((p) => p.part === n),
  );
  if (present.length > 0) {
    lines.push(
      "",
      `Support required -- ${present.join(", ")}.`,
      "These lie on their side on purpose: a spike carries its load along its",
      "axis, so printed upright the layers stack along that load and peel apart.",
      "Lying down runs them ACROSS it. What that costs is what they stand on, and",
      "it is not the same for both. Every other part stands on a flat face.",
      "",
    );
    // ONE ENTRY PER PART. The old note gave both the same sentence and sent
    // everyone to a brim, which cannot hold a part with no perimeter on the
    // plate. The measured figures live beside the list in src/lib/hex-support.
    for (const name of present) {
      const note = SUPPORT_NOTE[name];
      if (note) lines.push(...wrap72(`${name} ${note}`, "  "));
    }
    lines.push("", ...wrap72(SUPPORT_SLICER_NOTE, ""));
  }
  return lines;
}

function setReadme(
  label: string,
  names: string[],
  parts: ManifestPart[],
): string {
  return [
    `${label}`,
    "",
    "Hex Cluster modular tile system -- One Thousand Drones, LLC",
    "https://academy.onethousanddrones.com/hex",
    "",
    "Configure a cluster and generate a build sheet:",
    "  https://demo.onethousanddrones.com/hex",
    "",
    "Formats: 3mf/ (recommended -- carries units and part names)",
    "         stl/ (universal fallback)",
    "",
    // CORRECTED 2026-08-02. The 2026-07-31 release says "Printed in PLA at
    // 0.2 mm". The material is PETG, and the 0.25 mm design gap is toleranced
    // against PETG shrinkage, so it is not a free choice. That release is
    // immutable and stays wrong -- the /hex page is the authority, and this
    // text is corrected for the NEXT release. Composed from the SHARED spec
    // module so the archive and the page cannot drift apart.
    "Print settings:",
    ...HEX_PRINT_PARAMS.map(
      (p) =>
        `  ${p.label}: ${ascii(p.value)}${p.aside ? ` (${ascii(p.aside)})` : ""}`,
    ),
    ...HEX_CLEARANCE.map(
      (p) =>
        `  ${p.label}: ${ascii(p.value)}${p.aside ? ` (${ascii(p.aside)})` : ""}`,
    ),
    "",
    `Hex bases print ${HEX_ORIENTATION.value}. ${ascii(HEX_ORIENTATION.why)}`,
    "",
    // CORRECTED 2026-08-03. The 2026-07-31 release says flatly that "parts are
    // exported in their CAD orientation". That is wrong for a third of the set:
    // 16 of the 53 carry a baked -90 degree X rotation from the exporter. Worse,
    // it points the reader at the wrong risk. The risk is not that nothing was
    // rotated, it is that the rotations are DERIVED and every part in the
    // manifest still has printOrientationReviewed = false. Counted from the
    // manifest rather than typed in, so the sentence cannot drift from the set.
    ...orientationNote(parts),
    "",
    "Full spec: https://academy.onethousanddrones.com/hex",
    "",
    `Parts (${names.length}):`,
    ...names.map((n) => `  - ${n}`),
    "",
    "Licensed CC BY 4.0 -- see LICENSE.txt.",
  ].join("\n");
}

// CC BY 4.0: attribution is the only condition. Chosen deliberately over NC/SA.
// The parts are not the moat, enforcement against a functional printed object is
// thin under the useful-article doctrine, and both NC and SA suppress the remix
// volume that makes a listing rank. Mandated attribution IS the return here.
//
// NOTE: this is one-way. Files published under CC BY stay CC BY; only future
// releases can carry a different license.
const LICENSE_TXT = [
  "Hex Cluster modular tile system",
  "Copyright (c) One Thousand Drones, LLC",
  "",
  "This work is licensed under the Creative Commons Attribution 4.0",
  "International License (CC BY 4.0).",
  "",
  "You are free to:",
  "  Share  -- copy and redistribute in any medium or format",
  "  Adapt  -- remix, transform, and build upon it, for any purpose,",
  "            including commercially.",
  "",
  "Under the following term:",
  "  Attribution -- You must give appropriate credit to One Thousand",
  "  Drones, LLC, provide a link to this license, and indicate if changes",
  "  were made. You may do so in any reasonable manner, but not in any way",
  "  that suggests One Thousand Drones endorses you or your use.",
  "",
  "Full licence text: https://creativecommons.org/licenses/by/4.0/legalcode",
  "Summary:           https://creativecommons.org/licenses/by/4.0/",
  "",
  "Source: https://academy.onethousanddrones.com/hex",
].join("\n");

main().catch((err) => {
  console.error(err instanceof Error ? err.message : err);
  process.exit(1);
});
